import {ManualAiDomainAdapter} from '../../../adapters/manual_ai/domain-adapter.js';
import {ProviderAwareBackupIntegrationAdapter} from '../../../adapters/backup-runtime.js';
const assert=(v,m)=>{if(!v)throw Error(m)};
class Transport{constructor(){this.calls=[];this.pkg=0;this.previewMode='SUCCESS';}descriptor(){return {id:'CG6Corr01Transport'};}async request(method,path,body){this.calls.push({method,path,body});if(path==='/v1/backup/package'){this.pkg++;return {ok:true,status:'PACKAGE_VERIFIED',packageId:`pkg${this.pkg}`,manifestSha256:`m${this.pkg}`,snapshotSha256:`s${this.pkg}`,schemaArtifactSha256:`z${this.pkg}`,capturedAt:'2026-09-18T00:00:00Z'};}if(path.startsWith('/v1/backup/attempts'))return {ok:true,attempts:[]};if(path==='/v1/backup/preview')return this.previewMode==='CONFLICT'?{ok:false,status:'SCHEMA_CONFLICT',code:'PACKAGE_TARGET_SCHEMA_CONFLICT'}:{ok:true,status:'COMPATIBLE',packageId:body.packageId,writeEffects:{stageWrites:0,drillWrites:0,activationWrites:0,productionDatabaseWrites:0,liveRestoreWrites:0}};if(path==='/v1/backup/stage')return {ok:true,status:'STAGED',packageId:body.packageId,productionDatabaseMutated:false,liveRestored:false};if(path==='/v1/backup/drill')return {ok:true,status:'STAGED_AND_VERIFIED',drillId:`drill-${body.packageId}`,packageId:body.packageId,productionDatabaseMutated:false,liveRestored:false};return {ok:false,code:'UNEXPECTED'};}}
const results=[];async function run(id,fn){try{await fn();results.push({id,status:'PASS'});}catch(e){results.push({id,status:'FAIL',error:String(e?.message||e)});}}
await run('manual-ai.review-requires-imported-provenance-equal-result',()=>{const digest='a'.repeat(64),packageDigest='b'.repeat(64),a=new ManualAiDomainAdapter({io:{exportPackage:()=>({artifactId:'pkg',digest:packageDigest})}});a.prepare({proposalId:'p1',revision:'r1',sourceDigest:digest,sourceId:'src'});assert(a.availability('manual_ai.review',{id:'p1'})!==true,'review advertised before import');const pre=a.review({id:'p1',disposition:'REJECT'});assert(!pre.ok&&pre.code==='IMPORTED_PROPOSAL_REQUIRED','pre-import review must fail closed');a.export('p1');assert(a.availability('manual_ai.review',{id:'p1'})!==true,'review advertised after export but before provenance-equal import');const pre2=a.review({id:'p1',disposition:'DEFER'});assert(!pre2.ok&&pre2.code==='IMPORTED_PROPOSAL_REQUIRED','exported request cannot be reviewed before result import');const imported=a.import({proposalId:'p1',sourceId:'src',sourceRevisionId:'r1',sourceDigest:digest,packageDigest,content:'result'});assert(imported.ok&&a.availability('manual_ai.review',{id:'p1'})===true,'provenance-equal imported result must become reviewable');});
await run('backup.schema-conflict-is-visible-and-stage-unavailable',async()=>{const t=new Transport(),a=new ProviderAwareBackupIntegrationAdapter({transport:t});await a.createPackage();a.plan();t.previewMode='CONFLICT';const p=await a.preview();assert(!p.ok&&p.status==='SCHEMA_CONFLICT','provider conflict lost');assert(a.snapshot().preview?.schemaComparison?.conflict===true,'conflict not projected into preview state');assert(a.availability('backup.stage')!==true,'Stage advertised after conflict');const before=t.calls.filter(c=>c.path==='/v1/backup/stage').length,s=await a.stage(),after=t.calls.filter(c=>c.path==='/v1/backup/stage').length;assert(!s.ok&&s.code==='PROVIDER_PREVIEW_REQUIRED'&&before===after,'provider stage must not be called after conflict');});
await run('backup.drill-requires-stage-for-exact-selected-package',async()=>{const t=new Transport(),a=new ProviderAwareBackupIntegrationAdapter({transport:t});await a.createPackage();a.plan();await a.preview();await a.stage();await a.createPackage();assert(a.availability('backup.drill')!==true,'Drill advertised for a new package using stale stage receipt');const before=t.calls.filter(c=>c.path==='/v1/backup/drill').length,r=await a.drill(),after=t.calls.filter(c=>c.path==='/v1/backup/drill').length;assert(!r.ok&&r.code==='PROVIDER_STAGE_REQUIRED'&&before===after,'stale provider stage receipt must not authorize drill for another package');});
const summary={total:results.length,pass:results.filter(x=>x.status==='PASS').length,fail:results.filter(x=>x.status==='FAIL').length};console.log(JSON.stringify({status:summary.fail?'FAIL':'PASS',summary,results},null,2));if(summary.fail)process.exitCode=1;
